const payload = $json.body || {};
const orderNumber = payload.orderNumber || payload.order_id || payload.orderId || 'JMF-DEMO-2026';
const status = (payload.status || payload.result || 'SUCCESS').toUpperCase();
const amount = Number(payload.amount || payload.gross_amount || 150000);
const customer = payload.customer || payload.customerName || 'Budi Santoso';

// Generate direct URLs for JavaMifi Compass
const webBaseUrl = 'http://localhost:3000';
const apiBaseUrl = 'http://localhost:3001';

const redirectCallbackUrl = `${webBaseUrl}/id/payment/callback?order_id=${encodeURIComponent(orderNumber)}&status=${encodeURIComponent(status)}`;
const tripHubUrl = `${webBaseUrl}/id/trip-hub/${encodeURIComponent(orderNumber)}`;
const mockSimulatorUrl = `${webBaseUrl}/id/checkout/mock-payment?orderNumber=${encodeURIComponent(orderNumber)}&amount=${amount}&customer=${encodeURIComponent(customer)}`;

return {
  json: {
    orderNumber,
    status,
    amount,
    customer,
    redirectCallbackUrl,
    tripHubUrl,
    mockSimulatorUrl,
    apiEndpoint: `${apiBaseUrl}/payments/mock/callback`,
    isSuccess: status === 'SUCCESS' || status === 'SETTLEMENT'
  }
};

